import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, color, smoothstep, add, mul } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root group
  const root = new Group();
  root.userData.handlers = {};
  const cleanupFns = [];

  // ------- Textured Parallax Plane -------
  const planeWidth = 4.0;
  const planeHeight = 2.5;
  const seg = 64;

  const planeGeom = new PlaneGeometry(planeWidth, planeHeight, seg, seg);
  const planeMat = new MeshStandardNodeMaterial({
    color: new Color('#0b0b10'),
    transparent: true,
    opacity: 0,
    metalness: 0.0,
    roughness: 0.8,
  });

  // Node‑based color grading (filmic lift, contrast, desaturation)
  // simple approximation: mix dark lift and contrast via smoothstep
  const uvNode = uv();
  const liftColor = color('#0d0d12');
  const shadeColor = color('#e8ecf2');
  const lift = smoothstep(0.0, 0.45, uvNode.y);
  const shade = smoothstep(0.45, 1.0, uvNode.y);
  const gradedColor = mix(liftColor, shadeColor, lift);
  planeMat.colorNode = gradedColor;

  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load textures asynchronously
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  Promise.all([texPromise, depthPromise]).then(([tex, depth]) => {
    planeMat.map = tex;
    planeMat.displacementMap = depth;
    planeMat.displacementScale = 0.18;
    planeMat.needsUpdate = true;
  });

  // ------- Caption Scrim Gradient -------
  const scrimHeight = 1.0; // enough to hold text
  const scrimGeom = new PlaneGeometry(planeWidth, scrimHeight);
  const scrimMat = new MeshStandardNodeMaterial({
    transparent: true,
    metalness: 0.0,
    roughness: 0.8,
  });

  // Gradient: transparent -> #0b0b10eb
  const gradStart = color('#0b0b1000');
  const gradEnd = color('#0b0b10eb');
  const gradUv = uv();
  const gradFactor = smoothstep(0.45, 1.0, gradUv.y);
  scrimMat.colorNode = mix(gradStart, gradEnd, gradFactor);

  const scrimMesh = new Mesh(scrimGeom, scrimMat);
  scrimMesh.position.set(0, -planeHeight / 2 - scrimHeight / 2, 0.01);
  root.add(scrimMesh);

  // ------- Hairline Accent Bar -------
  const barGeom = new PlaneGeometry(0.75, 0.02);
  const barMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.8,
    metalness: 0.0,
    roughness: 0.8,
    transparent: true,
    opacity: 1,
  });
  const barMesh = new Mesh(barGeom, barMat);
  barMesh.position.set(0, 0.12, 0.02); // positioned between headline and body
  root.add(barMesh);

  // ------- Text Content -------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const captionGroup = new Group();
  const padding = 0.5;
  const baseline = 0.25;
  let cursorY = -planeHeight / 2 + padding; // start from bottom of scrim

  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 12,
      color: item.role === 'kicker' ? '#e8ecf2' : '#e8ecf2',
      align: 'left',
      letterSpacingPx: item.typography?.letterSpacing ?? 0,
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    txt.position.set(-planeWidth / 2 + padding, cursorY, 0.03);
    captionGroup.add(txt);
    cursorY += (opts.fontSize / 100) + baseline; // rough line height approximation
    // Insert hairline bar after headline
    if (item.role === 'headline') {
      barMesh.position.y = txt.position.y - baseline * 0.5;
    }
  }
  root.add(captionGroup);

  // ------- Animations -------
  const plateTimeline = gsap.timeline();
  plateTimeline.to(planeMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  cleanupFns.push(() => plateTimeline.kill());

  const captionTimeline = gsap.timeline({ delay: 0.12 });
  captionTimeline.from(captionGroup.position, {
    y: 0.4,
    opacity: 0,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });
  cleanupFns.push(() => captionTimeline.kill());

  // ------- Cinematic Primitive -------
  const primitivesList = config.cinematicPrimitives ?? [];
  const activePrimitives = [];
  for (const prim of primitivesList) {
    if (prim.name && ctx.primitives[prim.name]) {
      const p = ctx.primitives[prim.name](root, prim.params || {});
      activePrimitives.push(p);
      cleanupFns.push(() => p.cleanup && p.cleanup());
    }
  }

  // Ensure parallax-scroll is present (as required)
  if (!primitivesList.some(p => p.name === 'parallax-scroll')) {
    const p = ctx.primitives['parallax-scroll'](root, { intensity: 0.35 });
    activePrimitives.push(p);
    cleanupFns.push(() => p.cleanup && p.cleanup());
  }

  // ------- Cleanup -------
  root.userData.cleanup = () => {
    // Dispose geometries & materials
    planeGeom.dispose();
    planeMat.dispose();
    scrimGeom.dispose();
    scrimMat.dispose();
    barGeom.dispose();
    barMat.dispose();

    // Dispose textures if they were loaded
    texPromise.then(tex => tex.dispose && tex.dispose());
    depthPromise.then(tex => tex.dispose && tex.dispose());

    // Kill timelines
    cleanupFns.forEach(fn => fn());

    // Remove handlers placeholder
    root.userData.handlers = {};
  };

  return root;
}
